REVISE=[V,['拉丁语：revidēre → revīsere','再次看；重新察看'],['法语：réviser','再检查、修订'],['英语：revise','修改；复习']]
REVISION=[V,['拉丁语：revidēre → revīsiō','再看 → 再审查'],['法语：révision','重新审查、修订'],['英语：revision','修订；复习']]
